import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"从 Demo 到生产:Agent 还差什么?","description":"\\"能跑的 Demo\\" 和 \\"能上生产的 Agent\\" 之间,隔着五个缺口。","frontmatter":{},"headers":[],"relativePath":"agent/agent-advanced/0-why-advanced.md","filePath":"agent/agent-advanced/0-why-advanced.md","lastUpdated":1793113268000}'),o={name:"agent/agent-advanced/0-why-advanced.md"};function i(l,a,r,p,h,d){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="从-demo-到生产-agent-还差什么" tabindex="-1">从 Demo 到生产:Agent 还差什么? <a class="header-anchor" href="#从-demo-到生产-agent-还差什么" aria-label="Permalink to &quot;从 Demo 到生产:Agent 还差什么?&quot;">​</a></h1><blockquote><p>&quot;能跑的 Demo&quot; 和 &quot;能上生产的 Agent&quot; 之间,隔着五个缺口。</p></blockquote><h2 id="一、demo-和生产的差距" tabindex="-1">一、Demo 和生产的差距 <a class="header-anchor" href="#一、demo-和生产的差距" aria-label="Permalink to &quot;一、Demo 和生产的差距&quot;">​</a></h2><p>一个教程里的 Agent 通常长这样:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(question: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.invoke(question)</span></span></code></pre></div><p>能上生产的版本至少要处理:</p><ul><li>工具接进来要<strong>标准化</strong>(不能每个工具一套调用格式)</li><li>多个 Agent 要<strong>协作</strong>(不是一个 Agent 什么都干)</li><li>对话要<strong>记得住</strong>(跨会话)</li><li>答错了要<strong>能自我修正</strong></li><li>危险操作要<strong>人能拦住</strong></li></ul><p>下面五节,正好对应这五个缺口。</p><h2 id="二、五个缺口" tabindex="-1">二、五个缺口 <a class="header-anchor" href="#二、五个缺口" aria-label="Permalink to &quot;二、五个缺口&quot;">​</a></h2><h3 id="缺口-1-工具接入不标准化-→-mcp" tabindex="-1">缺口 1:工具接入不标准化 → MCP <a class="header-anchor" href="#缺口-1-工具接入不标准化-→-mcp" aria-label="Permalink to &quot;缺口 1:工具接入不标准化 → MCP&quot;">​</a></h3><p>每个工具自己定义 schema、自己解析参数、自己处理鉴权,工具一多就没法维护。</p><p><strong>MCP(Model Context Protocol)</strong> 把&quot;工具/资源/提示词&quot;的接入方式统一成一个协议:客户端(你的 Agent)连接 MCP Server,Server 暴露工具列表,调用方式完全一致。加一个新工具 = 起一个 MCP Server,不用改 Agent 代码。</p><h3 id="缺口-2-一个-agent-干不了所有事-→-multi-agent" tabindex="-1">缺口 2:一个 Agent 干不了所有事 → Multi-Agent <a class="header-anchor" href="#缺口-2-一个-agent-干不了所有事-→-multi-agent" aria-label="Permalink to &quot;缺口 2:一个 Agent 干不了所有事 → Multi-Agent&quot;">​</a></h3><p>把&quot;查数据库&quot;、&quot;写文案&quot;、&quot;做审核&quot;塞进一个 Agent,上下文会被撑爆,而且每一步的 prompt 都在互相干扰。</p><p><strong>Multi-Agent</strong> 的思路是拆:一个主 Agent 负责路由,几个子 Agent 各自专精(每个有独立的上下文和工具集),主 Agent 决定交给谁。</p><h3 id="缺口-3-对话记不住-→-memory" tabindex="-1">缺口 3:对话记不住 → Memory <a class="header-anchor" href="#缺口-3-对话记不住-→-memory" aria-label="Permalink to &quot;缺口 3:对话记不住 → Memory&quot;">​</a></h3><p>无状态意味着每轮对话都要把全部历史重新传一遍,token 成本线性增长,长对话还会超出窗口。</p><p><strong>Memory</strong> 分两层:短期(会话内滑动窗口 / 摘要压缩)+ 长期(向量库存用户偏好、事实,按需检索)。</p><h3 id="缺口-4-答错了没人纠正-→-reflection" tabindex="-1">缺口 4:答错了没人纠正 → Reflection <a class="header-anchor" href="#缺口-4-答错了没人纠正-→-reflection" aria-label="Permalink to &quot;缺口 4:答错了没人纠正 → Reflection&quot;">​</a></h3><p>Agent 一次输出就交付,错了也是错的。</p><p><strong>Reflection</strong> 模式让 Agent 自检:生成 → 批评 → 修正,循环直到通过。配合 LangGraph 就是天然的环。</p><h3 id="缺口-5-危险操作拦不住-→-human-in-the-loop" tabindex="-1">缺口 5:危险操作拦不住 → Human-in-the-Loop <a class="header-anchor" href="#缺口-5-危险操作拦不住-→-human-in-the-loop" aria-label="Permalink to &quot;缺口 5:危险操作拦不住 → Human-in-the-Loop&quot;">​</a></h3><p>付款、删除数据、对外发邮件 —— 这些必须有人点头。靠 Prompt 里写&quot;请谨慎&quot;是没用的,必须在执行层拦截。</p><h2 id="三、五个缺口的关系" tabindex="-1">三、五个缺口的关系 <a class="header-anchor" href="#三、五个缺口的关系" aria-label="Permalink to &quot;三、五个缺口的关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────┐</span></span>
<span class="line"><span>   工具标准化  ───▶ │                 │</span></span>
<span class="line"><span>   多 Agent   ───▶ │   生产级 Agent   │ ───▶ 可上线</span></span>
<span class="line"><span>   持久化记忆 ───▶ │                 │</span></span>
<span class="line"><span>   自我反思   ───▶ │                 │</span></span>
<span class="line"><span>   人工介入   ───▶ └─────────────────┘</span></span></code></pre></div><p>它们不是并列的五个技巧,而是<strong>从&quot;能跑&quot;到&quot;敢上线&quot;的五个必要条件</strong>。少一个,Agent 就会以某种方式在生产环境出事:</p><table tabindex="0"><thead><tr><th>缺了</th><th>后果</th></tr></thead><tbody><tr><td>工具标准化</td><td>工具越多越难维护,加一个改一片</td></tr><tr><td>Multi-Agent</td><td>上下文爆炸、成本失控</td></tr><tr><td>Memory</td><td>token 成本线性增长,长对话失效</td></tr><tr><td>Reflection</td><td>错误直接交付给用户</td></tr><tr><td>Human-in-the-Loop</td><td>误操作不可逆</td></tr></tbody></table><h2 id="四、这一节的读法" tabindex="-1">四、这一节的读法 <a class="header-anchor" href="#四、这一节的读法" aria-label="Permalink to &quot;四、这一节的读法&quot;">​</a></h2><p>后续章节是按这个顺序展开的:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1-intro            本节内容的地图</span></span>
<span class="line"><span>2-mcp              缺口 1:工具接入标准化</span></span>
<span class="line"><span>3-multi-agent      缺口 2:多 Agent 协作</span></span>
<span class="line"><span>4-memory           缺口 3:短期与长期记忆</span></span>
<span class="line"><span>5-reflection       缺口 4:自我反思与修正(含 Human-in-the-Loop)</span></span></code></pre></div><p>其中「人工审批与中断恢复」在 LangGraph 里实现得更完整,配套实战见 <a href="/agent/学习计划/项目B-Agent工作台/07-Human-in-the-Loop">项目 B · 第七步:Human-in-the-Loop</a>。</p><p><strong>建议先看 <code>1-intro</code> 的总览图,再按缺口挑着读。</strong> 如果你只是想让 Demo 跑通,这一节可以先跳过;如果准备上生产,五节都要过一遍。</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><p><strong>Q1:一个 Agent 要上生产,需要补齐哪些能力?</strong> 五个方面:工具接入标准化(MCP)、多 Agent 分工、记忆(短期窗口 + 长期检索)、反思自纠、人工审批介入。这五项分别对应&quot;可维护、可扩展、可负担、可靠、可控&quot;。</p><p><strong>Q2:为什么需要 Multi-Agent,一个 Agent 加更多工具不行吗?</strong> 工具一多,每个工具的 schema 都进上下文,既费 token 又互相干扰;而且不同任务需要的上下文完全不同。拆成子 Agent 后,每个子 Agent 只带自己那套工具和上下文,主 Agent 只做路由。</p><p><strong>Q3:Reflection 有什么风险?</strong> 反思循环可能陷入死循环,也可能把正确答案&quot;反思&quot;成错误答案。所以要给最大轮数、超时和&quot;不再修改就交付&quot;的兜底策略。</p><p><strong>Q4:Human-in-the-Loop 一定要放在执行层吗?</strong> 是。写在 Prompt 里(&quot;执行前请先确认&quot;)只是建议,模型可能不遵守;放在执行层(工具调用前挂起,等人放行)才是真正的拦截。LangGraph 的 <code>interrupt_before</code> 就是干这个的。</p><h2 id="📚-延伸阅读" tabindex="-1">📚 延伸阅读 <a class="header-anchor" href="#📚-延伸阅读" aria-label="Permalink to &quot;📚 延伸阅读&quot;">​</a></h2><ul><li><a href="/agent/agent-advanced/1-intro">Agent 进阶 总览</a></li><li><a href="/agent/agent-advanced/2-mcp">MCP 协议</a></li><li><a href="/agent/agent-advanced/3-multi-agent">Multi-Agent</a></li><li><a href="/agent/学习计划/项目B-Agent工作台/07-Human-in-the-Loop">Human-in-the-Loop 实战</a></li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>Demo 与生产的差距不在模型,在工程:工具标准化、多 Agent、记忆、反思、人工介入这五项。</li><li>五项缺失分别对应五种生产事故,可维护性、可扩展性、成本、可靠性、可控性。</li><li>Reflection 必须配最大轮数与兜底,否则会自我否定或死循环。</li><li>Human-in-the-Loop 必须在执行层拦截,Prompt 层面的&quot;请谨慎&quot;没有强制力。</li></ul>`,41)])])}const u=t(o,[["render",i]]);export{c as __pageData,u as default};
